<script setup lang="ts">
import {computed,ref} from 'vue';import {useRoute,useRouter} from 'vue-router';import {usePhase1} from '@/pinia/phase1';import {agentWorkData} from '@/pinia/agentWork';import {dateText,eventNames,phaseSkills} from './catalog';import Clock from './Clock.vue';import CorrectionDialog from './CorrectionDialog.vue';
const route=useRoute();const router=useRouter();const s=usePhase1();const work=agentWorkData();const search=ref('');const type=ref('');const active=ref('');const correction=ref('');
const events=computed(()=>s.events.filter(e=>e.projectId===work.currentProjectId&&(!route.query.orderId||e.orderId===route.query.orderId)&&(!type.value||e.type===type.value)&&(!search.value||`${e.id} ${e.orderId} ${e.address} ${e.result}`.includes(search.value))).slice().reverse());
const selected=computed(()=>s.events.find(e=>e.id===(active.value||route.query.eventId)&&e.projectId===work.currentProjectId));
const localResults=computed(()=>s.anomalies.filter(a=>['晚发','晚到'].includes(a.kind)&&s.orders.some(o=>o.id===a.orderId&&o.projectId===work.currentProjectId)&&(!route.query.orderId||a.orderId===route.query.orderId)));
</script>
<template><div class="p1-desk"><header><h1>基础事件列表</h1><span>V1.1 · 事实与固定规则结果</span><button @click="router.push('/index/risk')">异常运单</button></header><Clock/><p class="p1-muted">四类自研事件和恶劣天气事件独立保存，直接显示规则结果；晚发晚到来源于本地计时，不冒充第五类外部事件。</p><div v-if="route.query.orderId" class="p1-warning">运单范围 {{route.query.orderId}} <button @click="router.replace('/index/events')">清除范围</button></div><div class="p1-toolbar"><input v-model="search" aria-label="搜索基础事件" placeholder="事件 / 运单 / 地点 / 结果"/><select v-model="type" aria-label="基础事件类型"><option value="">全部类型</option><option v-for="(name,key) in eventNames" :key="key" :value="key">{{name}}</option></select><span>{{events.length}}条</span></div><div class="p1-table"><table><thead><tr><th>事件 / 运单</th><th>基础事实</th><th>发生 / 接收时间</th><th>固定规则结果</th><th>负责的任务</th><th>配置</th><th>操作</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td><strong>{{e.id}}</strong><small>{{e.orderId}}</small></td><td>{{eventNames[e.type]}} · {{e.phase==='recovered'?'解除':e.phase==='enter'?'进入':e.phase==='exit'?'离开':'告警'}}<small>{{e.address}} {{e.type==='weather'?`${e.weatherType} · ${e.message}`:e.type==='deviation'?`${e.distanceMeters}米`:e.type==='fence'?'':`${e.durationMinutes}分钟`}}</small></td><td>{{dateText(e.occurredAt)}}<small>{{dateText(e.receivedAt)}}</small></td><td>{{e.result}}</td><td><button v-for="id in e.taskIds" :key="id" @click="router.push({path:'/index/daily-tasks',query:{projectId:e.projectId,taskId:id,orderId:e.orderId}})">{{phaseSkills.find(t=>t.id===id)?.name}}</button><small v-if="!e.taskIds.length">未选状态任务，事实保留</small></td><td>v{{e.configVersion}}</td><td><button @click="active=e.id">详情</button><button @click="correction=e.id">纠正结果</button></td></tr></tbody></table><p v-if="!events.length" class="p1-empty">暂无基础事件。可到运单详情模拟围栏、告警及恢复。</p></div><h2>本地晚发晚到结果</h2><article v-for="a in localResults" :key="a.id" class="p1-row"><strong>{{a.orderId}} · {{a.kind}} · {{a.status==='active'?'未恢复':a.status==='corrected'?'已纠正':'已恢复'}}</strong><p>{{a.reason}}</p><button @click="correction=a.id">纠正结果</button><small>本地计时 · {{a.id}} · 配置v{{a.configVersion}}</small></article><p v-if="!localResults.length" class="p1-muted">暂无本地超时结果。</p>
<div v-if="selected" class="p1-overlay"><section class="p1-dialog" role="dialog" aria-modal="true" aria-label="基础事件详情"><header><h2>{{eventNames[selected.type]}} · {{selected.id}}</h2><button @click="active='';router.replace({path:'/index/events',query:{orderId:route.query.orderId}})">关闭</button></header><p>{{selected.orderId}} · {{selected.address}}</p><p v-if="selected.type==='weather'">{{selected.weatherType}} · {{selected.message}}<br/>消息ID：{{selected.sourceMessageId}} · 不发送车机提醒</p><p>发生{{dateText(selected.occurredAt)}} · 接收{{dateText(selected.receivedAt)}}</p><p>来源：本地模拟基础接口回调 · 配置v{{selected.configVersion}}</p><h2>固定规则结果</h2><p>{{selected.result}}</p><button @click="correction=selected.id">纠正结果</button><details v-if="selected.corrections?.length"><summary>原始结果与纠正记录</summary><p>{{selected.originalResult}}</p><p v-for="(c,i) in selected.corrections" :key="i">{{dateText(c.at)}} · {{c.operator}}：{{c.after}}；{{c.reason}}</p></details><p class="p1-muted">原始事实不会因后续配置调整或异常恢复被覆盖。</p><button @click="router.push({path:'/index/detail',query:{orderId:selected.orderId}})">运单详情</button></section></div><CorrectionDialog v-if="correction" :key="correction" :id="correction" @close="correction=''"/></div></template>
<style src="./phase.css"></style>
